{\it Assume that $(X,\omega)$ satisfies (H1), (H2) and (H3).  
Let  $F(x,t)$ be a continuous function which is increasing in $t$ and  assume that there 
exist $t_0, t_1\in \mathbb{R}$ such that 
\begin{equation}\label{eq: V4}
F(x,t_0)\leq 1\leq F(x,t_1),\ \forall x\in X.
\end{equation}
Then there exists a unique viscosity solution to 
$$
-(\omega+dd^c\varphi)^m\wedge \omega^{n-m}+F(x,\varphi)\omega^n=0.
$$}

\label{def: viscosity subsolution} 
An upper semicontinuous function $\varphi: \Omega\rightarrow \mathbb{R}\cup \{-\infty\}$ is  a viscosity subsolution to
\begin{equation}\label{eq: heq 1}
-(dd^c \varphi)^m\wedge \beta^{n-m}+F(x,\varphi)\beta^n=0
\end{equation}
if $\varphi\not\equiv -\infty$ and for any $x_0\in \Omega$ and any $\mathcal{C}^2$ function $q$ which touches $\varphi$ from above at $x_0$ then 
$$
H_m(q)\geq F(x,q)\beta^n, \ \text{at}\ x_0.
$$
Here we use the notation $H_m(u)=(dd^cu)^m\wedge \beta^{n-m}$ for $u\in \mathcal{C}^2(X).$ We also say that $H_m(\varphi)\geq F(x,q)\beta^n$ \enquote{in the viscosity sense}.

\label{lem: decreasing sequence of viscosity subsolution}
Assume that $F: \Omega\times \mathbb{R}\rightarrow \mathbb{R}^+$ is a continuous function. Let $(\varphi_j)$ be a monotone sequence of viscosity subsolutions of equation
\begin{equation}\label{eq: limsup}
-(dd^c u)^m\wedge \beta^{n-m} + F(x,u)\beta^n=0,
\end{equation}
If $\varphi_j$ is uniformly bounded from above  and $\varphi:=(\lim\varphi_j)^*\not \equiv -\infty$ then $\varphi$ is also a viscosity subsolution of (\ref{eq: limsup}).

\label{lem: viscosity sense and usual sense}  A function $u$ is $m$-subharmonic in $\Omega$  if and only if it is a viscosity subsolution of
\begin{equation}\label{eq: potential vs viscosity 0 rhs}
-(dd^c u)^m\wedge \beta^{n-m}= 0.
\end{equation}

\label{prop: viscosity subsolution vs potential subsolution continuous rhs}
Let $\varphi$ be a bounded upper semicontinuous function in $\Omega$ and $0\leq f$ be a continuous function. 

(i) If $\varphi$ is $m$-subharmonic such that 
\begin{equation}\label{eq: viscosity vs potential 1}
H_m(\varphi)\geq f\beta^n
\end{equation} 
in the potential sense then it also holds in the viscosity sense. 

(ii) Conversely, if (\ref{eq: viscosity vs potential 1}) holds in the viscosity sense then $\varphi$ is $m$-subharmonic and the inequality holds in the potential sense.

\label{thm: viscosity vs potential general case}
Let $F: \Omega\times \mathbb{R}\to \mathbb{R}^+$ be a continuous function which is non-decreasing in the second variable. Let $\varphi$ be a bounded u.s.c. function in $\Omega.$ Then the inequality 
\begin{equation}\label{eq: viscosity vs potential 2}
H_m(\varphi)\geq F(x,\varphi)\beta^n
\end{equation}
holds in the viscosity sense if and only if $\varphi$ is $m$-subharmonic in $\Omega$ and (\ref{eq: viscosity vs potential 2}) holds in the potential sense.

Let us prove the first implication. Assume that (\ref{eq: viscosity vs potential 2}) holds in the viscosity sense.
Consider the sup-convolution of $\varphi$:
\begin{equation}\label{eq: sup-convolution local}
\varphi^{\delta}(x):=\sup\{\varphi(y)-\frac{1}{\delta^2}\vert x-y\vert^2 \ / \  y\in \Omega\}, \ x\in \Omega_{\delta},
\end{equation}
where $\Omega_{\delta}:=\{x\in \Omega \ /\  d(x,\partial \Omega)>A\delta\},$ and the positive constant $A$ is chosen so that $A^2>\text{osc}_{\Omega}\varphi.$ Then $\varphi^{\delta}\downarrow \varphi$ and  as in \cite{Ish89} (see also \cite{EGZ11}) it can be shown  that
\begin{equation}\label{eq: viscosity vs potential 3}
H_m(\varphi^{\delta})\geq F_{\delta}(x,\varphi^{\delta})\beta^n, \ \text{in} \ \Omega_{\delta},
\end{equation}
in the viscosity sense, where $F_{\delta}(x,t)=\inf_{\vert y-x\vert\leq A\delta} F(y,t).$

It follows from Proposition \ref{prop: viscosity subsolution vs potential subsolution continuous rhs} that (\ref{eq: viscosity vs potential 3}) holds in the potential sense and the result follows by letting $\delta$ go to $0.$ 

Let us prove the other implication. Suppose that $\varphi$ satisfies (\ref{eq: viscosity vs potential 2}) in the potential sense.  As in \cite{EGZ11} it can be shown  that 
\begin{equation}\label{eq: viscosity vs potential 4}
H_m(\varphi^{\delta})\geq F_{\delta}(x,\varphi^{\delta})\beta^n,
\end{equation}
in the potential sense. Now,  applying Proposition
 \ref{prop: viscosity subsolution vs potential subsolution
  continuous rhs} to $\varphi^{\delta}$ we see that 
  (\ref{eq: viscosity vs potential 4}) holds in the 
  viscosity sense. It suffices to let $\delta\to 0.$

\label{prop: viscosity vs potential hom}
Assume that  $\omega$ is K\"{a}hler and $\varphi$ is a continuous function on $X.$ Then $\varphi$ is $(\omega,m)$-subharmonic iff 
\begin{equation}\label{eq: viscosity vs potential hom}
(\omega+dd^c\varphi)^m \wedge \omega^{n-m}\geq 0
\end{equation}
in the viscosity sense.

\label{thm: viscosity vs potential hom}
Assume that $\omega$ is K\"{a}hler, $F$ is continuous on $X\times \mathbb{R}$ and increasing in the second variable, and $\varphi\in \mathcal{C}(X).$ Then $\varphi$ is $(\omega,m)$-subharmonic and satisfies 
\begin{equation}\label{eq: viscosity vs potential hom 2}
(\omega+dd^c\varphi)^m\wedge\omega^{n-m}\geq F(x,\varphi)\omega^n
\end{equation} 
in the potential sense  if and only if  the above inequality holds in the viscosity sense.
